type userWhere[Q psql.Filterable] struct {
	ID           psql.WhereMod[Q, int64]
	AuthProvider psql.WhereMod[Q, string]
	AuthSubject  psql.WhereMod[Q, string]
	Email        psql.WhereNullMod[Q, string]
	Name         psql.WhereNullMod[Q, string]
	CreatedAt    psql.WhereMod[Q, time.Time]
	UpdatedAt    psql.WhereMod[Q, time.Time]
}

func (userWhere[Q]) AliasedAs(alias string) userWhere[Q] {
	return buildUserWhere[Q](buildUserColumns(alias))
}

func buildUserWhere[Q psql.Filterable](cols userColumns) userWhere[Q] {
	return userWhere[Q]{
		ID:           psql.Where[Q, int64](cols.ID),
		AuthProvider: psql.Where[Q, string](cols.AuthProvider),
		AuthSubject:  psql.Where[Q, string](cols.AuthSubject),
		Email:        psql.WhereNull[Q, string](cols.Email),
		Name:         psql.WhereNull[Q, string](cols.Name),
		CreatedAt:    psql.Where[Q, time.Time](cols.CreatedAt),
		UpdatedAt:    psql.Where[Q, time.Time](cols.UpdatedAt),
	}
}

func (o *User) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Articles":
		rels, ok := retrieved.(ArticleSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Articles = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
			}
		}
		return nil
	case "ExternalTokens":
		rels, ok := retrieved.(ExternalTokenSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.ExternalTokens = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
			}
		}
		return nil
	case "Prompts":
		rels, ok := retrieved.(PromptSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Prompts = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
			}
		}
		return nil
	case "Transcriptions":
		rels, ok := retrieved.(TranscriptionSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Transcriptions = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
			}
		}
		return nil
	default:
		return fmt.Errorf("user has no relationship %q", name)
	}
}

type userPreloader struct{}

func buildUserPreloader() userPreloader {
	return userPreloader{}
}

type userThenLoader[Q orm.Loadable] struct {
	Articles       func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	ExternalTokens func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Prompts        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Transcriptions func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildUserThenLoader[Q orm.Loadable]() userThenLoader[Q] {
	type ArticlesLoadInterface interface {
		LoadArticles(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ExternalTokensLoadInterface interface {
		LoadExternalTokens(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PromptsLoadInterface interface {
		LoadPrompts(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type TranscriptionsLoadInterface interface {
		LoadTranscriptions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return userThenLoader[Q]{
		Articles: thenLoadBuilder[Q](
			"Articles",
			func(ctx context.Context, exec bob.Executor, retrieved ArticlesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadArticles(ctx, exec, mods...)
			},
		),
		ExternalTokens: thenLoadBuilder[Q](
			"ExternalTokens",
			func(ctx context.Context, exec bob.Executor, retrieved ExternalTokensLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadExternalTokens(ctx, exec, mods...)
			},
		),
		Prompts: thenLoadBuilder[Q](
			"Prompts",
			func(ctx context.Context, exec bob.Executor, retrieved PromptsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPrompts(ctx, exec, mods...)
			},
		),
		Transcriptions: thenLoadBuilder[Q](
			"Transcriptions",
			func(ctx context.Context, exec bob.Executor, retrieved TranscriptionsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadTranscriptions(ctx, exec, mods...)
			},
		),
	}
}

// LoadArticles loads the user's Articles into the .R struct
func (o *User) LoadArticles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Articles = nil

	related, err := o.Articles(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.User = o
	}

	o.R.Articles = related
	return nil
}

// LoadArticles loads the user's Articles into the .R struct
func (os UserSlice) LoadArticles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	articles, err := os.Articles(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Articles = nil
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range articles {

			if !(o.ID == rel.UserID) {
				continue
			}

			rel.R.User = o

			o.R.Articles = append(o.R.Articles, rel)
		}
	}

	return nil
}

