type userJoins[Q dialect.Joinable] struct {
	typ            string
	Articles       modAs[Q, articleColumns]
	ExternalTokens modAs[Q, externalTokenColumns]
	Prompts        modAs[Q, promptColumns]
	Transcriptions modAs[Q, transcriptionColumns]
}

func (j userJoins[Q]) aliasedAs(alias string) userJoins[Q] {
	return buildUserJoins[Q](buildUserColumns(alias), j.typ)
}

func buildUserJoins[Q dialect.Joinable](cols userColumns, typ string) userJoins[Q] {
	return userJoins[Q]{
		typ: typ,
		Articles: modAs[Q, articleColumns]{
			c: Articles.Columns,
			f: func(to articleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Articles.Name().As(to.Alias())).On(
						to.UserID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		ExternalTokens: modAs[Q, externalTokenColumns]{
			c: ExternalTokens.Columns,
			f: func(to externalTokenColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ExternalTokens.Name().As(to.Alias())).On(
						to.UserID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Prompts: modAs[Q, promptColumns]{
			c: Prompts.Columns,
			f: func(to promptColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Prompts.Name().As(to.Alias())).On(
						to.UserID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Transcriptions: modAs[Q, transcriptionColumns]{
			c: Transcriptions.Columns,
			f: func(to transcriptionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Transcriptions.Name().As(to.Alias())).On(
						to.UserID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
